import{_ as a,o as r,c as i,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"एकाधिकार-विरोधी कानून","description":"","frontmatter":{},"headers":[],"relativePath":"hi/47-反垄断法.md","filePath":"hi/47-反垄断法.md","lastUpdated":1789183869000}'),e={name:"hi/47-反垄断法.md"};function d(o,t,n,h,s,b){return r(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="एकाधिकार-विरोधी-कानून" tabindex="-1">एकाधिकार-विरोधी कानून <a class="header-anchor" href="#एकाधिकार-विरोधी-कानून" aria-label="Permalink to &quot;एकाधिकार-विरोधी कानून&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>47</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>एकाधिकार-विरोध, निष्पक्ष प्रतिस्पर्धा, सहजीवी बाज़ार-व्यवस्था, शिकारी कृत्यों का निषेध, दस हजार जातियों के साझा उन्नयन की रक्षा</td></tr></tbody></table><h2 id="i-विधायी-उद्देश्य-और-मूल-सिद्धांत" tabindex="-1">I. विधायी उद्देश्य और मूल सिद्धांत <a class="header-anchor" href="#i-विधायी-उद्देश्य-और-मूल-सिद्धांत" aria-label="Permalink to &quot;I. विधायी उद्देश्य और मूल सिद्धांत&quot;">​</a></h2><p><em>एकाधिकार-विरोधी कानून</em> लंगर सहजीवी सभ्यता के पाँच सहायक कानूनों में से एक है। इसका उद्देश्य साधना-संसाधनों, साधना-संप्रदायों, वाणिज्यिक बाज़ारों आदि क्षेत्रों में एकाधिकार और शिकारी कृत्यों को रोकना, हेंग-ब्रह्मांड की निष्पक्ष प्रतिस्पर्धा और सहजीवी बाज़ार-व्यवस्था बनाए रखना, और यह सुनिश्चित करना है कि कोई भी शक्ति या संगठन एकाधिकार द्वारा विकास-अवसर न छीन सके, जिससे &quot;दस हजार जातियों का साझा उन्नयन&quot; सुनिश्चित हो।</p><p>यह कानून निम्न मूल सिद्धांत स्थापित करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>निष्पक्ष प्रतिस्पर्धा</td><td>सभी विषय समान आधार पर प्रतिस्पर्धा करते हैं; बाज़ार-प्रभुत्व का दुरुपयोग और अनुचित प्रतिस्पर्धा निषिद्ध</td></tr><tr><td>खुला बाज़ार</td><td>एकाधिकार-समझौते, बाज़ार-विभाजन, प्रतिस्पर्धा को बहिष्कृत या सीमित करने वाले प्रतिबंध निषिद्ध</td></tr><tr><td>दुर्बल-संरक्षण</td><td>नवीन साधकों, प्रारंभिक जातियों, लघु-मध्यम संगठनों के प्रति झुकावपूर्ण संरक्षण</td></tr><tr><td>सहजीवी व्यवस्था</td><td>बाज़ार को दस हजार जातियों के साझा उन्नयन की सेवा करनी चाहिए; पूँजी और सत्ता द्वारा जनहित-लूट निषिद्ध</td></tr><tr><td>एकीकृत प्रवर्तन</td><td>एकाधिकार-विरोधी प्रवर्तन एकीकृत संस्था द्वारा; स्थानीय संरक्षणवाद और अंतर-पटल एकाधिकारी कृत्य निषिद्ध</td></tr></tbody></table><h2 id="ii-एकाधिकार-की-परिभाषा" tabindex="-1">II. एकाधिकार की परिभाषा <a class="header-anchor" href="#ii-एकाधिकार-की-परिभाषा" aria-label="Permalink to &quot;II. एकाधिकार की परिभाषा&quot;">​</a></h2><p>यह कानून निम्न कृत्यों को एकाधिकारी कृत्य घोषित करता है, जो निषिद्ध हैं:</p><ol><li><strong>एकाधिकार-समझौते</strong>: प्रतिस्पर्धियों के बीच या ऊपरी-निचली व्यावसायिक इकाइयों के बीच मूल्य-निर्धारण, बाज़ार-विभाजन, उत्पादन-सीमा, बहिष्कार आदि समझौते।</li><li><strong>बाज़ार-प्रभुत्व का दुरुपयोग</strong>: अनुचित उच्च मूल्य पर बेचना, लागत से नीचे बेचना, अनुचित लेनदेन-शर्तें थोपना, लेनदेन-अस्वीकार, जोड़-बिक्री आदि।</li><li><strong>संचालक-संकेंद्रण</strong>: विलय, अधिग्रहण, संयुक्त उद्यम जो प्रतिस्पर्धा समाप्त या सीमित करते हैं; एकाधिकार-विरोधी प्राधिकरण में पूर्व-घोषणा और समीक्षा अनिवार्य।</li><li><strong>प्रशासनिक एकाधिकार</strong>: राज्य-अंगों और सार्वजनिक संगठनों द्वारा प्रतिस्पर्धा सीमित करने हेतु प्रशासनिक-सत्ता का दुरुपयोग, स्थानीय संरक्षणवाद, क्षेत्रीय एकाधिकार।</li><li><strong>साधना-संसाधन एकाधिकार</strong>: साधना-संसाधनों, आत्मा-ऊर्जा केंद्र-बिंदुओं, गुप्त-क्षेत्रों पर एकाधिकारी नियंत्रण, अन्यों को साधना से बहिष्कृत करना।</li><li><strong>प्रतिभा-एकाधिकार</strong>: अनुचित साधनों से साधना-प्रतिभाओं का अनन्य नियंत्रण, प्रतिभाओं के मुक्त प्रवाह को सीमित करना।</li></ol><h2 id="iii-एकाधिकार-विरोधी-संस्थाएँ" tabindex="-1">III. एकाधिकार-विरोधी संस्थाएँ <a class="header-anchor" href="#iii-एकाधिकार-विरोधी-संस्थाएँ" aria-label="Permalink to &quot;III. एकाधिकार-विरोधी संस्थाएँ&quot;">​</a></h2><p>सहजीवी न्यायालय और उसकी अधीनस्थ एकाधिकार-विरोधी प्रवर्तन संस्थाएँ निम्न कार्य करती हैं:</p><table tabindex="0"><thead><tr><th>संस्था</th><th>कार्य</th></tr></thead><tbody><tr><td>एकाधिकार-विरोधी प्रवर्तन ब्यूरो</td><td>एकाधिकारी कृत्यों की जाँच, संदिग्ध एकाधिकारी कृत्यों पर जाँच-आरंभ</td></tr><tr><td>एकाधिकार समीक्षा समिति</td><td>संचालक-संकेंद्रण और बाज़ार-संरचना परिवर्तनों की समीक्षा</td></tr><tr><td>मूल्य-निगरानी कार्यालय</td><td>महत्वपूर्ण साधना-संसाधनों और वस्तुओं के मूल्य-व्यवहार की निगरानी</td></tr><tr><td>अंतर-पटल समन्वय कार्यालय</td><td>पटलों के बीच एकाधिकार-विरोधी प्रवर्तन का समन्वय, अंतर-पटल एकाधिकार की रोकथाम</td></tr></tbody></table><p>एकाधिकार-विरोधी प्रवर्तन संस्था को जाँच-अधिकार प्राप्त हैं: संबंधित पक्षों से स्पष्टीकरण माँगना, पुस्तकें-लेखे निरीक्षण करना, साक्ष्य सील-जब्त करना आदि। जाँच-विषयों का सहयोग अनिवार्य; इनकार और बाधा निषिद्ध।</p><h2 id="iv-साधना-संसाधन-एकाधिकार-पर-विशेष-प्रावधान" tabindex="-1">IV. साधना-संसाधन एकाधिकार पर विशेष प्रावधान <a class="header-anchor" href="#iv-साधना-संसाधन-एकाधिकार-पर-विशेष-प्रावधान" aria-label="Permalink to &quot;IV. साधना-संसाधन एकाधिकार पर विशेष प्रावधान&quot;">​</a></h2><p>साधना-संसाधन हेंग-ब्रह्मांड की सार्वजनिक संपत्ति हैं; यह कानून उनके एकाधिकार-रोकथाम हेतु विशेष प्रावधान स्थापित करता है:</p><ol><li><strong>संसाधन-पहुँच समानता</strong>: सभी जातियों और साधकों को साधना-संसाधनों तक समान पहुँच-अधिकार; कोई संप्रदाय या संगठन मूल संसाधनों पर अनन्य अधिकार नहीं कर सकता।</li><li><strong>आत्मा-ऊर्जा केंद्र-बिंदु साझाकरण</strong>: प्रमुख आत्मा-ऊर्जा केंद्र-बिंदुओं पर साझा-प्रबंधन प्रणाली; अनन्य अधिग्रहण और निजी साधना-क्षेत्र स्थापना निषिद्ध।</li><li><strong>गुप्त-क्षेत्र खुली प्रणाली</strong>: किसी भी विषय द्वारा खोजे गए गुप्त-क्षेत्र प्रबंधन-संस्था को घोषित कर सार्वजनिक संसाधन-प्रणाली में शामिल करने अनिवार्य; गुप्त अधिग्रहण निषिद्ध।</li><li><strong>गोली-बाज़ार विनियमन</strong>: महत्वपूर्ण गोलियाँ और आत्मीय-औषधियाँ मूल्य-मार्गदर्शन और आपूर्ति-निगरानी के अधीन; जमाखोरी और मूल्य-वृद्धि निषिद्ध।</li><li><strong>कलाकृति-संचार निगरानी</strong>: उच्च-स्तरीय कलाकृतियों का संचार पंजीकृत-प्रबंधित; कलाकृति-स्रोतों पर नियंत्रण द्वारा सशस्त्र कलाकृति-एकाधिकार स्थापना निषिद्ध।</li></ol><h2 id="v-उपचार-और-कानूनी-दायित्व" tabindex="-1">V. उपचार और कानूनी दायित्व <a class="header-anchor" href="#v-उपचार-और-कानूनी-दायित्व" aria-label="Permalink to &quot;V. उपचार और कानूनी दायित्व&quot;">​</a></h2><p>एकाधिकारी कृत्यों के लिए यह कानून निम्न उपचार और दायित्व प्रदान करता है:</p><ul><li><strong>रोक-आदेश</strong>: एकाधिकार-विरोधी प्रवर्तन संस्था एकाधिकारी कृत्य रोकने का आदेश देती है।</li><li><strong>जुर्माना</strong>: अवैध आय और परिस्थितियों की गंभीरता के अनुसार जुर्माना।</li><li><strong>अवैध आय जब्ती</strong>: एकाधिकारी कृत्यों से प्राप्त अवैध आय जब्त।</li><li><strong>योग्यता-निरस्तीकरण</strong>: गंभीर परिस्थितियों में व्यापार-लाइसेंस या साधना-संप्रदाय योग्यताएँ निरस्त।</li><li><strong>क्षति-क्षतिपूर्ति</strong>: एकाधिकारी कृत्यों के पीड़ितों को क्षतिपूर्ति-दावे का अधिकार।</li><li><strong>आपराधिक दायित्व</strong>: एकाधिकारी कृत्य अपराध-गठन पर आपराधिक दायित्व।</li></ul><h2 id="vi-जनहित-वाद" tabindex="-1">VI. जनहित-वाद <a class="header-anchor" href="#vi-जनहित-वाद" aria-label="Permalink to &quot;VI. जनहित-वाद&quot;">​</a></h2><p>जनहित को हानि पहुँचाने वाले एकाधिकारी कृत्यों के लिए निम्न विषय सहजीवी न्यायालय में एकाधिकार-विरोधी जनहित-वाद दायर कर सकते हैं:</p><ul><li>एकाधिकार-विरोधी प्रवर्तन संस्थाएँ</li><li>सहजीवी जनहित-संगठन</li><li>कानून द्वारा निर्धारित अन्य विषय</li></ul><p>जनहित-वाद का उद्देश्य एकाधिकारी कृत्य रोकना, बाज़ार-व्यवस्था के जनहित की रक्षा और जनहित-क्षति की क्षतिपूर्ति है।</p><h2 id="vii-कानून-का-प्रयोग" tabindex="-1">VII. कानून का प्रयोग <a class="header-anchor" href="#vii-कानून-का-प्रयोग" aria-label="Permalink to &quot;VII. कानून का प्रयोग&quot;">​</a></h2><p>यह कानून हेंग-ब्रह्मांड के भीतर होने वाले सभी एकाधिकारी कृत्यों पर लागू होता है, जिसमें हेंग-ब्रह्मांड की अधिकारिता में अन्य ब्रह्मांडों के विषयों के एकाधिकारी कृत्य भी शामिल हैं। ब्रह्मांडों के पार होने वाले एकाधिकारी कृत्यों पर पारस्परिकता और परामर्श सिद्धांत लागू होता है।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>एकाधिकार-विरोधी कानून</em> लंगर सहजीवी सभ्यता की &quot;दस हजार जातियों के साझा उन्नयन&quot; दर्शन की कानूनी ढाल है। एकाधिकारी कृत्यों को परिभाषित और दंडित करके, समर्पित संस्थाएँ स्थापित करके, साधना-संसाधन एकाधिकार को विनियमित करके यह सहजीवी बाज़ार की निष्पक्षता और खुलापन सुनिश्चित करता है, किसी भी शक्ति द्वारा संसाधनों और विकास-अवसरों की लूट रोकता है, दस हजार जातियों के साझा उन्नयन के लिए संस्थागत गारंटी प्रदान करता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>42-消费者保护法 (उपभोक्ता संरक्षण कानून)</li><li>41-共生劳动法 (सहजीवी श्रम कानून)</li><li>07-联产承包机制详解 (संयुक्त-उत्पादन ठेका तंत्र का विस्तृत विवरण)</li></ul>',29)])])}const p=a(e,[["render",d]]);export{u as __pageData,p as default};
